"""Render a dependency-free Chinese EvalPlan review application."""

# ruff: noqa: E501, RUF001 -- standalone Chinese HTML is intentionally kept readable.

from __future__ import annotations

import html
import json

from gepase.evals.eval_plan import EvalPlanCheckReport, EvalPlanDraft, EvalReviewSubmission
from gepase.package.ir import PackageGraph


def _script_json(value: object) -> str:
    if hasattr(value, "model_dump"):
        value = value.model_dump(mode="json")  # type: ignore[union-attr]
    return json.dumps(value, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")


def render_eval_review(
    draft: EvalPlanDraft,
    draft_hash: str,
    checks: EvalPlanCheckReport,
    graph: PackageGraph,
    state: str = "awaiting_review",
    existing_review: EvalReviewSubmission | None = None,
) -> str:
    package_files = sorted({node.path for node in graph.nodes if node.kind.value == "file"})
    seeded_decisions = []
    if existing_review is not None:
        for item in existing_review.decisions:
            value = item.model_dump(mode="json")
            if item.edited_case is not None:
                value["edited_text"] = json.dumps(item.edited_case, ensure_ascii=False, indent=2)
            seeded_decisions.append(value)
    reviewer_id = existing_review.reviewer_id if existing_review is not None else ""
    reviewer_kind = existing_review.reviewer_kind if existing_review is not None else "human"
    return f"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>GEPASE · EvalPlan 人工审核</title>
<style>
:root{{--paper:#f6f3ed;--surface:#fffdf9;--ink:#23221f;--muted:#706e67;--line:#d9d4ca;--accent:#b54c2f;--accent2:#245f55;--soft:#eee8de;--ok:#2d6b4f;--warn:#9b6418;--bad:#9d332b;--mono:ui-monospace,SFMono-Regular,Menlo,monospace}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 -apple-system,BlinkMacSystemFont,"PingFang SC","Noto Sans CJK SC","Microsoft YaHei",sans-serif}}button,input,select,textarea{{font:inherit}}header{{padding:56px clamp(24px,7vw,100px) 36px;border-bottom:1px solid var(--line);background:linear-gradient(135deg,#fffdf9 0%,#f2ece1 100%)}}.eyebrow{{font:600 12px/1 var(--mono);letter-spacing:.16em;color:var(--accent);text-transform:uppercase}}h1{{font:500 clamp(32px,5vw,58px)/1.08 Georgia,"Songti SC",serif;max-width:900px;margin:18px 0}}.lead{{max-width:820px;color:var(--muted);font-size:17px}}.status-row{{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}}.pill{{padding:6px 11px;border:1px solid var(--line);border-radius:99px;background:#ffffffa8;font-size:13px}}.layout{{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:32px;max-width:1440px;margin:auto;padding:34px clamp(20px,4vw,64px) 100px}}main{{min-width:0}}aside{{position:sticky;top:20px;height:max-content;border:1px solid var(--line);border-radius:14px;background:var(--surface);padding:20px}}nav a{{display:block;color:var(--ink);text-decoration:none;padding:8px 0;border-bottom:1px solid var(--soft)}}h2{{font:500 30px/1.2 Georgia,"Songti SC",serif;margin:48px 0 10px}}h3{{font-size:18px;margin:0}}.section-intro{{color:var(--muted);max-width:850px}}.explain{{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin:18px 0}}.explain div{{border-top:2px solid var(--ink);padding:10px 4px;color:var(--muted)}}.explain b{{display:block;color:var(--ink);margin-bottom:4px}}.toolbar{{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--surface);margin:18px 0}}input[type=search],input[type=text],select{{border:1px solid var(--line);background:white;border-radius:8px;padding:9px 11px}}input[type=search]{{min-width:250px;flex:1}}button{{border:1px solid var(--ink);border-radius:8px;background:var(--ink);color:white;padding:9px 13px;cursor:pointer}}button.secondary{{background:white;color:var(--ink);border-color:var(--line)}}button.accent{{background:var(--accent);border-color:var(--accent)}}button:focus,input:focus,select:focus,textarea:focus{{outline:3px solid #b54c2f33;outline-offset:1px}}.card{{border:1px solid var(--line);border-radius:14px;background:var(--surface);margin:14px 0;overflow:hidden}}.card-head{{display:flex;gap:16px;align-items:flex-start;justify-content:space-between;padding:18px 20px;background:#fff}}.meta{{display:flex;flex-wrap:wrap;gap:7px;margin-top:7px}}.tag{{font:12px/1.3 var(--mono);padding:4px 7px;background:var(--soft);border-radius:5px}}.tag.validation{{background:#e1eee9;color:var(--accent2)}}.card-body{{padding:0 20px 20px}}.prompt{{padding:14px;border-left:3px solid var(--accent);background:#faf6ef;border-radius:0 8px 8px 0}}details{{margin-top:14px}}summary{{cursor:pointer;font-weight:600}}.case-json{{width:100%;min-height:300px;margin-top:10px;border:1px solid var(--line);border-radius:8px;background:#20211f;color:#f6f3ed;padding:12px;font:12px/1.5 var(--mono);tab-size:2}}.decision{{display:flex;flex-wrap:wrap;gap:9px;align-items:center;margin-top:16px;padding-top:14px;border-top:1px solid var(--soft)}}.decision select{{min-width:190px}}.decision input{{flex:1;min-width:240px}}.pending{{color:var(--warn)}}.approved{{color:var(--ok)}}.rejected{{color:var(--bad)}}.checks{{display:grid;gap:8px}}.check{{display:grid;grid-template-columns:90px 1fr;gap:12px;border-bottom:1px solid var(--soft);padding:10px 0}}.check strong{{font:12px/1.5 var(--mono)}}.graph-shell{{border:1px solid var(--line);border-radius:14px;background:#21231f;color:#f9f6ee;overflow:hidden}}.graph-controls{{display:flex;gap:12px;align-items:center;padding:12px 16px;background:#2b2d28}}#graph{{width:100%;min-height:540px;display:block;overflow:auto}}.node rect{{fill:#343831;stroke:#807d70}}.node text{{fill:#f4efe6;font:10px var(--mono);pointer-events:none}}.edge{{stroke:#77766d;stroke-width:1;opacity:.35}}.node.active rect{{stroke:#e28a66;stroke-width:2}}#graph-detail{{white-space:pre-wrap;word-break:break-word;padding:15px;margin:0;background:#171815;max-height:220px;overflow:auto;font:12px/1.45 var(--mono)}}.review-box{{display:grid;gap:10px}}.review-box label{{font-weight:600}}.review-box input,.review-box select{{width:100%}}.progress{{height:8px;background:var(--soft);border-radius:99px;overflow:hidden;margin:12px 0}}.progress i{{display:block;height:100%;width:0;background:var(--accent2);transition:width .2s}}.notice{{padding:12px;border-radius:8px;background:#f7eadc;color:#76431f;margin:12px 0}}code{{font-family:var(--mono);font-size:.9em}}footer{{border-top:1px solid var(--line);padding:28px clamp(24px,7vw,100px);color:var(--muted)}}@media(max-width:960px){{.layout{{grid-template-columns:1fr}}aside{{position:static;order:-1}}}}@media print{{aside,.toolbar,.decision,button{{display:none!important}}body{{background:white}}.card{{break-inside:avoid}}}}
</style></head><body>
<header><div class="eyebrow">GEPASE / R2 / {html.escape(state)}</div><h1>在执行 Agent 之前，先把评测计划审清楚。</h1><p class="lead">这是一份可离线打开的 EvalPlan 审核页。语义化测试由隔离的 Eval Designer 起草，Core 已完成结构、fixture、许可、重复、泄漏和弱断言检查；你的决定会导出为 <code>review.json</code>，再由 Core 校验并冻结 revision。若当前 revision 已冻结，本页仅用于审计或为新 revision 准备意见，不能覆盖既有计划。</p><div class="status-row"><span class="pill">Package：{html.escape(draft.package_id)}</span><span class="pill">Snapshot：{draft.package_snapshot_hash[:12]}…</span><span class="pill">Draft：{draft_hash[:12]}…</span><span class="pill">Trigger：{len(draft.trigger_cases)}</span><span class="pill">Functional：{len(draft.functional_cases)}</span><span class="pill">自动检查：{"通过" if checks.valid else "未通过"}</span></div></header>
<div class="layout"><main>
<section id="guide"><h2>审核说明</h2><p class="section-intro">审核不是重新写一遍 benchmark。重点确认任务是否真实、是否覆盖 Skill 能力边界、validation 是否值得保留，以及 grader 看见的 expectations/rubric 是否合理。Executor 在后续只会收到 prompt、fixture 和 requested output，不会收到这些 oracle。</p><div class="explain"><div><b>approve</b>原样保留该 case。</div><div><b>edit</b>修改下方完整 JSON 后保留，Core 会重新校验。</div><div><b>reject</b>从 frozen plan 排除，必须说明原因。</div><div><b>request-regeneration</b>退回 Eval Designer，当前 revision 不会冻结。</div></div></section>
<section id="checks"><h2>自动检查</h2><p class="section-intro">机器检查只能拦截结构性问题，不能替代对语义质量的判断。</p><div class="checks">{"".join(f'<div class="check"><strong>{html.escape(item.status.value)}</strong><span><b>{html.escape(item.check_id)}</b><br>{html.escape(item.detail_zh)}</span></div>' for item in checks.checks)}</div></section>
<section id="graph-section"><h2>Package Graph</h2><p class="section-intro">图来自完整 Package snapshot。默认展示 Package、文件和依赖节点；可以显示细粒度 Markdown/Python 节点并点击检查稳定 node id、路径和 metadata。</p><div class="graph-shell"><div class="graph-controls"><label><input id="fine" type="checkbox"> 显示细粒度节点</label><span>{len(graph.nodes)} nodes · {len(graph.edges)} edges · {len(graph.diagnostics)} diagnostics</span></div><svg id="graph" aria-label="Package Graph"></svg><pre id="graph-detail">点击节点查看详情。</pre></div></section>
<section id="cases"><h2>Eval cases</h2><p class="section-intro">Trigger 与 Functional 是两条独立评分通道。页面筛选只影响显示，不改变导出的决定集合。</p><div class="toolbar"><input id="search" type="search" placeholder="搜索 case、family、prompt…"><select id="type-filter"><option value="all">全部类型</option><option value="trigger">Trigger</option><option value="functional">Functional</option></select><select id="split-filter"><option value="all">全部 split</option><option value="train">Train</option><option value="validation">Validation</option></select><select id="risk-filter"><option value="all">全部风险</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select><button class="secondary" id="approve-low">批量确认低风险 Train</button></div><div id="case-list"></div></section>
</main><aside><nav><a href="#guide">审核说明</a><a href="#checks">自动检查</a><a href="#graph-section">Package Graph</a><a href="#cases">Eval cases</a></nav><h3 style="margin-top:22px">审核进度</h3><div class="progress"><i id="progress-bar"></i></div><p id="progress-text" class="pending">0 / 0 已决定</p><div class="review-box"><label for="reviewer">Reviewer ID</label><input id="reviewer" type="text" value="{html.escape(reviewer_id)}" placeholder="例如 didi-maintainer"><label for="reviewer-kind">Reviewer 类型</label><select id="reviewer-kind"><option value="human">human</option><option value="maintainer">maintainer</option><option value="agent-assisted">agent-assisted</option></select><button class="accent" id="export-review">导出 review.json</button><button class="secondary" id="reset-review">清除本页决定</button></div><p class="notice" id="message">未决 case 必须为 0 才能导出。页面不会上传任何数据。</p><h3>Package 文件</h3><p style="font:12px/1.6 var(--mono);word-break:break-all">{"<br>".join(html.escape(path) for path in package_files)}</p></aside></div>
<footer>GEPASE EvalPlan Review · 自包含离线页面 · 不含外部脚本、字体或分析代码。</footer>
<script type="application/json" id="draft-data">{_script_json(draft)}</script><script type="application/json" id="graph-data">{_script_json(graph)}</script>
<script>
const draft=JSON.parse(document.getElementById('draft-data').textContent);const graph=JSON.parse(document.getElementById('graph-data').textContent);const draftHash='{draft_hash}';
const cases=[...draft.trigger_cases,...draft.functional_cases];const seededDecisions={_script_json(seeded_decisions)};const decisions=new Map(seededDecisions.map(d=>[d.case_id,d]));const list=document.getElementById('case-list');document.getElementById('reviewer-kind').value='{html.escape(reviewer_kind)}';
function esc(s){{return String(s).replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]))}}
function summary(c){{return c.case_type==='trigger'?c.query:c.prompt}}
function renderCases(){{const q=document.getElementById('search').value.toLowerCase(),tf=document.getElementById('type-filter').value,sf=document.getElementById('split-filter').value,rf=document.getElementById('risk-filter').value;list.innerHTML='';cases.forEach(c=>{{const hay=JSON.stringify(c).toLowerCase();if((q&&!hay.includes(q))||(tf!=='all'&&c.case_type!==tf)||(sf!=='all'&&c.split!==sf)||(rf!=='all'&&c.risk!==rf))return;const card=document.createElement('article');card.className='card';card.dataset.id=c.case_id;const d=decisions.get(c.case_id)||{{decision:'pending',comment_zh:''}};card.innerHTML=`<div class="card-head"><div><h3>${{esc(c.case_id)}}</h3><div class="meta"><span class="tag">${{esc(c.case_type)}}</span><span class="tag ${{c.split}}">${{esc(c.split)}}</span><span class="tag">${{esc(c.risk)}}</span>${{c.case_family?`<span class="tag">${{esc(c.case_family)}}</span>`:''}}</div></div><span class="${{d.decision==='approve'||d.decision==='edit'?'approved':d.decision==='reject'?'rejected':'pending'}}">${{esc(d.decision)}}</span></div><div class="card-body"><div class="prompt">${{esc(summary(c))}}</div><details><summary>字段解释与完整 JSON（选择 edit 时可修改）</summary><p>Trigger 的 expected_trigger 仅供触发指标；Functional 的 expected_output、expectations 与 rubric 只提供给独立 Grader，不进入 Executor view。</p><textarea class="case-json" spellcheck="false">${{esc(d.edited_text||JSON.stringify(c,null,2))}}</textarea></details><div class="decision"><select class="decision-select"><option value="pending">请选择决定</option><option value="approve">approve</option><option value="edit">edit</option><option value="reject">reject</option><option value="request_regeneration">request-regeneration</option></select><input class="comment" type="text" placeholder="编辑说明；reject/regeneration 必填"></div></div>`;card.querySelector('.decision-select').value=d.decision;card.querySelector('.comment').value=d.comment_zh||'';card.querySelector('.decision-select').addEventListener('change',e=>{{const old=decisions.get(c.case_id)||{{}};decisions.set(c.case_id,{{...old,decision:e.target.value,comment_zh:card.querySelector('.comment').value,edited_text:card.querySelector('.case-json').value}});updateProgress();renderCases()}});card.querySelector('.comment').addEventListener('input',e=>{{const old=decisions.get(c.case_id)||{{decision:'pending'}};decisions.set(c.case_id,{{...old,comment_zh:e.target.value}})}});card.querySelector('.case-json').addEventListener('input',e=>{{const old=decisions.get(c.case_id)||{{decision:'pending',comment_zh:''}};decisions.set(c.case_id,{{...old,edited_text:e.target.value}})}});list.appendChild(card)}})}}
function updateProgress(){{const done=cases.filter(c=>{{const d=decisions.get(c.case_id);return d&&d.decision!=='pending'}}).length;document.getElementById('progress-bar').style.width=`${{done/cases.length*100}}%`;const t=document.getElementById('progress-text');t.textContent=`${{done}} / ${{cases.length}} 已决定`;t.className=done===cases.length?'approved':'pending'}}
['search','type-filter','split-filter','risk-filter'].forEach(id=>document.getElementById(id).addEventListener('input',renderCases));document.getElementById('approve-low').addEventListener('click',()=>{{cases.filter(c=>c.split==='train'&&c.risk==='low').forEach(c=>decisions.set(c.case_id,{{decision:'approve',comment_zh:'批量确认低风险 train case'}}));renderCases();updateProgress()}});document.getElementById('reset-review').addEventListener('click',()=>{{decisions.clear();renderCases();updateProgress()}});
document.getElementById('export-review').addEventListener('click',()=>{{const reviewer=document.getElementById('reviewer').value.trim(),message=document.getElementById('message');if(!reviewer){{message.textContent='请填写 Reviewer ID。';return}}const pending=cases.filter(c=>!decisions.get(c.case_id)||decisions.get(c.case_id).decision==='pending');if(pending.length){{message.textContent=`仍有 ${{pending.length}} 个未决 case。`;return}}const rows=[];for(const c of cases){{const d=decisions.get(c.case_id);const row={{case_id:c.case_id,case_type:c.case_type,decision:d.decision,comment_zh:d.comment_zh||''}};if(d.decision==='edit'){{try{{row.edited_case=JSON.parse(d.edited_text||JSON.stringify(c))}}catch(e){{message.textContent=`${{c.case_id}} 的 JSON 无效：${{e.message}}`;return}}}}if((d.decision==='reject'||d.decision==='request_regeneration')&&!row.comment_zh.trim()){{message.textContent=`${{c.case_id}} 必须填写原因。`;return}}rows.push(row)}}const payload={{schema_version:'1.0.0',review_id:`review-${{Date.now()}}`,plan_id:draft.plan_id,draft_hash:draftHash,reviewer_id:reviewer,reviewer_kind:document.getElementById('reviewer-kind').value,decisions:rows,submitted_at:new Date().toISOString()}};const blob=new Blob([JSON.stringify(payload,null,2)+'\\n'],{{type:'application/json'}}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='review.json';a.click();URL.revokeObjectURL(a.href);message.textContent='review.json 已导出；请用 gepase eval import-review 导入。'}});
function drawGraph(){{const fine=document.getElementById('fine').checked;const visible=graph.nodes.filter(n=>fine||['package','file','dependency'].includes(n.kind));const known=new Set(visible.map(n=>n.node_id)),cols=fine?8:4,cellW=fine?170:250,cellH=fine?72:92;const pos=new Map(visible.map((n,i)=>[n.node_id,[95+(i%cols)*cellW,60+Math.floor(i/cols)*cellH]]));const width=Math.max(820,cols*cellW),height=Math.max(520,120+Math.ceil(visible.length/cols)*cellH),svg=document.getElementById('graph');svg.setAttribute('viewBox',`0 0 ${{width}} ${{height}}`);svg.innerHTML='';graph.edges.filter(e=>known.has(e.source)&&known.has(e.target)).forEach(e=>{{const [x1,y1]=pos.get(e.source),[x2,y2]=pos.get(e.target),line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',x1);line.setAttribute('y1',y1);line.setAttribute('x2',x2);line.setAttribute('y2',y2);line.setAttribute('class','edge');svg.appendChild(line)}});visible.forEach(n=>{{const [x,y]=pos.get(n.node_id),g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('class','node');g.setAttribute('transform',`translate(${{x}},${{y}})`);g.setAttribute('tabindex','0');const rect=document.createElementNS('http://www.w3.org/2000/svg','rect');rect.setAttribute('x','-78');rect.setAttribute('y','-23');rect.setAttribute('width','156');rect.setAttribute('height','46');rect.setAttribute('rx','7');const text=document.createElementNS('http://www.w3.org/2000/svg','text');text.setAttribute('text-anchor','middle');text.setAttribute('y','3');text.textContent=(n.label||n.path).slice(0,22);g.append(rect,text);const show=()=>{{document.querySelectorAll('.node').forEach(x=>x.classList.remove('active'));g.classList.add('active');document.getElementById('graph-detail').textContent=JSON.stringify(n,null,2)}};g.addEventListener('click',show);g.addEventListener('keydown',e=>{{if(e.key==='Enter'||e.key===' ')show()}});svg.appendChild(g)}})}}document.getElementById('fine').addEventListener('change',drawGraph);renderCases();updateProgress();drawGraph();
</script></body></html>"""
